package com.guocheng.mediapocket;
import java.nio.*;import java.nio.charset.*;import java.util.*;
final class SubtitleTextRules {
 static String decode(byte[] b)throws Exception{if(b.length>2*1024*1024)throw new Exception("字幕文件过大");if(b.length>1&&b[0]==(byte)0xff&&b[1]==(byte)0xfe)return new String(b,"UTF-16LE").replace("\ufeff","");if(b.length>1&&b[0]==(byte)0xfe&&b[1]==(byte)0xff)return new String(b,"UTF-16BE").replace("\ufeff","");try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString().replace("\ufeff","");}catch(CharacterCodingException e){return new String(b,"GB18030");}}
 static String timeline(String text){if(!text.contains("[Events]"))return text;boolean events=false;String[] format={"Layer","Start","End","Style","Name","MarginL","MarginR","MarginV","Effect","Text"};StringBuilder out=new StringBuilder();int index=0;for(String raw:text.replace("\r","").split("\n")){String line=raw.trim();if(line.startsWith("[")){events=line.equalsIgnoreCase("[Events]");continue;}if(!events)continue;if(line.startsWith("Format:")){format=line.substring(7).trim().split("\\s*,\\s*");continue;}if(!line.startsWith("Dialogue:"))continue;String[] cols=line.substring(9).trim().split(",",format.length);if(cols.length!=format.length)continue;int start=-1,end=-1,body=-1;for(int i=0;i<format.length;i++){if(format[i].equalsIgnoreCase("Start"))start=i;else if(format[i].equalsIgnoreCase("End"))end=i;else if(format[i].equalsIgnoreCase("Text"))body=i;}if(start<0||end<0||body!=format.length-1)continue;try{String value=cols[body].replaceAll("\\{[^}]*\\}","").replace("\\N","\n").replace("\\n","\n").replace("\\h"," ");String from=time(cols[start]),to=time(cols[end]);if(value.trim().isEmpty())continue;out.append(++index).append('\n').append(from).append(" --> ").append(to).append('\n').append(value).append("\n\n");}catch(Exception ignored){}}return out.toString();}
 static String time(String raw){String[] p=raw.trim().split(":");if(p.length!=3)throw new IllegalArgumentException();int h=Integer.parseInt(p[0]),m=Integer.parseInt(p[1]);double sec=Double.parseDouble(p[2]);if(h<0||m<0||m>59||sec<0||sec>=60)throw new IllegalArgumentException();int ms=(int)Math.round(sec*1000);return String.format(Locale.ROOT,"%02d:%02d:%02d,%03d",h,m,ms/1000,ms%1000);}
}
